gvu(){return"\u041e\u0442\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u0438\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u0435"},
gpi(){return"\u0418\u0437\u0431\u0440\u0430\u043d\u043d\u043e\u0435"},
